// User-provided target recordings, audio only. See USER-AUDIO-SOURCE-v23.txt.
const encoded={build:'',cast:'',inventory:'',coins:''};
const cache=new Map();
export function userActionRecording(kind,sampleRate=22050){const key=['build','cast'].includes(kind)?kind:kind==='sell'?'coins':['buy','pickup','bag','harvest','catch'].includes(kind)?'inventory':null;if(!key)return null;let data=cache.get(key);if(!data){const b=Uint8Array.from(atob(encoded[key]),c=>c.charCodeAt(0)),v=new DataView(b.buffer);data=Float32Array.from({length:b.length/2},(_,i)=>v.getInt16(i*2,true)/32768);cache.set(key,data);}if(sampleRate===22050)return data.slice();return Float32Array.from({length:Math.ceil(data.length*sampleRate/22050)},(_,i)=>{const p=i*22050/sampleRate,a=Math.floor(p),f=p-a;return(data[a]??0)*(1-f)+(data[a+1]??0)*f;});}
